tool_calls.arguments:
{"command":"mkdir -p /etc/coredns && cat > /etc/coredns/Corefile << 'EOF'
.:53 {
    errors
    health
    ready
    kubernetes cluster.local in-addr.arpa ip6.arpa {
        pods insecure
        fallthrough in-addr.arpa ip6.arpa
    }
    prometheus :9153
    forward . /etc/resolv.conf
    loadbalance
}
EOF"}

